/// The table `XMP::PrintLensID` names for a maker, or an empty one
/// where ExifTool's is empty too.
#[must_use]
pub fn table(name: &str) -> Option<&'static [(&'static str, &'static str)]> {
    Some(match name {
        "canonLensTypes" => CANONLENSTYPES,
        "nikonLensIDs" => NIKONLENSIDS,
        "pentaxLensTypes" => PENTAXLENSTYPES,
        "sonyLensTypes" => SONYLENSTYPES,
        "sigmaLensTypes" => SIGMALENSTYPES,
        "samsungLensTypes" => SAMSUNGLENSTYPES,
        "leicaLensTypes" => LEICALENSTYPES,
        "sonyLensTypes2" => SONYLENSTYPES2,
        "sigmaLensTypesFull" => SIGMALENSTYPESFULL,
        "metabonesID" => METABONESID,
        _ => return None,
    })
}
